/**
 * @method
 * @name scwin.chkEmail
 * @author Inswave
 * @date 2026. 09. 29
 * @param el
 * @returns
 * @hidden N
*/
scwin.chkEmail = async function (el) {
    /* sdd-asis-lifecycle:begin chkEmail — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const val = el.value;
    if (val !== "") {
        const pattern = /^[_a-zA-Z0-9-\.]+@[\.a-zA-Z0-9-]+\.[a-zA-Z]+$/;
        if (!pattern.test(val)) {
            await $c.win.alert("E-mail 형식에 맞지않습니다.");
            el.focus();
        }
    }
    /* sdd-asis-lifecycle:end */
};


async function chkPhone(el) {
    /* sdd-asis-lifecycle:begin chkPhone — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const val = el.value;
    if (val !== "") {
        const pattern = /^(0[2-8][0-5]?|01[01346-9])-?([1-9]{1}[0-9]{2,3})-?([0-9]{4})$/;
        if (!pattern.test(val)) {
            await $c.win.alert("전화번호 형식에 맞지않습니다.");
            el.focus();
        }
    }
    /* sdd-asis-lifecycle:end */
}

