    const spacMergeObjBzProcsNo = $c.util.getComponent("ipt_spacMergeObjBzProcsNo");
    if (('' !== isurCd) && (isurCd.length == 5)) {
        objCd.setValue(isurCd);
        objIsurCd.setValue(isurCd);
    } else {
        await $c.win.alert('선택하신 법인의 고유코드가 존재하지 않거나 올바르지 않습니다.\n' + '헬프데스크로 문의바랍니다.');
        return;
    }
    if ('' !== ipt_comNm_2) {
        objNm.setValue(ipt_comNm_2);
        objEngNm.setValue(ipt_comEngNm);
        objAbbrvNm.setValue(ipt_comAbbrv_2);
        objEngAbbrvNm.setValue(ipt_comEngAbbrv);
    } else {
        await $c.win.alert('선택하신 법인의 회사명이 존재하지 않거나 올바르지 않습니다.\n' + '헬프데스크로 문의바랍니다.');
        return;
    }
    if ('' !== corpRegNo) {
        $c.util.getComponent("ipt_corpRegNo1").setValue(corpRegNo.substring(0, 7));
        $c.util.getComponent("ipt_corpRegNo2").setValue(corpRegNo.substring(7, 14));
    } else {
        await $c.win.alert('선택하신 법인의 법인등록번호가 존재하지 않거나 올바르지 않습니다.\n' + '헬프데스크로 문의바랍니다.');
        return;
    }
    if ('' !== bzRegNo) {
        $c.util.getComponent("ipt_bzRegNo1").setValue(bzRegNo.substring(0, 3));
        $c.util.getComponent("ipt_bzRegNo2").setValue(bzRegNo.substring(3, 5));
        $c.util.getComponent("ipt_bzRegNo3").setValue(bzRegNo.substring(5, 10));
    } else {
        await $c.win.alert('선택하신 법인의 사업자등록번호가 존재하지 않거나 올바르지 않습니다.\n' + '헬프데스크로 문의바랍니다.');
        return;
    }
    if ('' !== spacObjBzProcsNo) {
        $c.util.getComponent("dma_comInfo").set("spacMergeObjBzProcsNo", spacObjBzProcsNo);
    } else {
        await $c.win.alert('선택하신 법인의 업무처리번호가 존재하지 않거나 올바르지 않습니다.\n' + '헬프데스크로 문의바랍니다.');
        return;
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.confirm
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.confirm = async function () {
    /* sdd-asis-lifecycle:begin fn_confirm — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const objIsurCd = $c.util.getComponent("ipt_spacLapsMergeIsurCd");
    if ((objIsurCd.getValue() == null ? '' : String(objIsurCd.getValue())) === '') {
        if (await $c.win.confirm("상장유형이 SPAC-소멸합병인 경우 SPAC인 상장법인을 반드시 입력해야 합니다.\n입력하시려면 [확인] 버튼을 클릭하세요.")) {
            scwin.searchSpacListCompany();
        }
        return false;
    }
    return true;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.setSpacLapsCorpInfo
 * @author Inswave
 * @date 2026. 09. 29
 * @param isurCd spacComNm
 * @returns
 * @hidden N
*/
scwin.setSpacLapsCorpInfo = async function (isurCd, spacComNm) {
    /* sdd-asis-lifecycle:begin setSpacLapsCorpInfo — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const objNm = $c.util.getComponent("ipt_spacCorpNm");
    const objCd = $c.util.getComponent("ipt_spacLapsMergeIsurCd");
    if (('' !== isurCd) && (isurCd.length == 5)) {
        objCd.setValue(isurCd);
    } else {
        await $c.win.alert('선택하신 법인의 고유코드가 존재하지 않거나 올바르지 않습니다.\n' + '헬프데스크로 문의바랍니다.');
        return;
    }
    if ('' !== spacComNm) {
        objNm.setValue(spacComNm);
    } else {
        await $c.win.alert('선택하신 법인의 회사명이 존재하지 않거나 올바르지 않습니다.\n' + '헬프데스크로 문의바랍니다.');
    }
    /* sdd-asis-lifecycle:end */
};



